import React from "react";
import { useEditorSelector } from "platejs/react";
import { AlignLeft, AlignCenter, AlignRight, JustifiedAlignment } from "@exp-textura/icons";

/**
 * Subscribe to the current block's text alignment.
 *
 * Must be used inside a `<RichText>` (or `<Plate>`) context.
 * Requires `@platejs/basic-styles` with `TextAlignPlugin` configured.
 *
 * @param editorId - Optional editor ID when multiple editors exist under a `PlateController`
 * @returns The alignment string: `"left"`, `"center"`, `"right"`, or `"justify"`. Defaults to `"left"`.
 *
 * @example
 * const alignment = useAlignment();
 * const icon = getAlignmentIcon(alignment);
 */
export function useAlignment(editorId?: string): string {
  return useEditorSelector(
    (ed) => {
      if (!ed) return "left";
      const node = ed?.api?.block()?.[0];
      return (node?.align as string) || "left";
    },
    [],
    ...(editorId ? [{ id: editorId }] : []),
  );
}

/**
 * Map an alignment value to its corresponding Textura icon component.
 *
 * @param alignment - One of `"left"`, `"center"`, `"right"`, `"justify"`
 * @returns The matching Textura icon element
 *
 * @example
 * const alignment = useAlignment();
 * <DropdownIconButton>{getAlignmentIcon(alignment)}</DropdownIconButton>
 */
export function getAlignmentIcon(alignment: string): React.ReactElement {
  switch (alignment) {
    case "center":
      return React.createElement(AlignCenter);
    case "right":
      return React.createElement(AlignRight);
    case "justify":
      return React.createElement(JustifiedAlignment);
    default:
      return React.createElement(AlignLeft);
  }
}
